package tv.vela.launcher;

import android.app.*;import android.content.*;import android.database.*;import android.graphics.*;import android.os.*;import android.view.*;import java.io.*;import java.lang.reflect.*;import java.text.*;import java.util.*;

/** Actual Lite remote paging and corrected logo precedence, with a read-only tuner/EPG fixture. */
public final class LiteTvRegressionTest extends Instrumentation {
    public static final class Provider extends ContentProvider {public boolean onCreate(){return true;}public Cursor query(android.net.Uri u,String[] p,String s,String[] a,String o){return new MatrixCursor(new String[]{"_id"});}public String getType(android.net.Uri u){return "vnd.android.cursor.dir/channel";}public android.net.Uri insert(android.net.Uri u,ContentValues v){throw new UnsupportedOperationException();}public int update(android.net.Uri u,ContentValues v,String s,String[] a){throw new UnsupportedOperationException();}public int delete(android.net.Uri u,String s,String[] a){throw new UnsupportedOperationException();}}
    static final class Data extends LiteAntennaData {final Context c;int reads;Data(Context context){super(context);c=context;}boolean permitted(){return true;}boolean refreshGuide(List<LiveTvData.Channel> all,CancellationSignal signal){return false;}List<LiveTvData.Channel> channels(CancellationSignal signal)throws Exception{reads++;List<LiveTvData.Channel> out=new ArrayList<>();Field logo=LiveTvData.Channel.class.getDeclaredField("logo");logo.setAccessible(true);for(int i=1;i<=36;i++){LiveTvData.Channel ch=new LiveTvData.Channel(i,"owned-fixture",Integer.toString(i),String.format(Locale.ROOT,"Canal Demo %02d",i),false,true,false,"dvb:"+i);logo.set(ch,android.net.Uri.fromFile(new File(c.getCacheDir(),"tv-regression-native.png")).toString());out.add(ch);}return out;}Map<String,List<LiveTvData.Programme>> programmes(List<LiveTvData.Channel> page,long from,long to,CancellationSignal signal){return new LiteXmlTvGuide(c).read(page,from,to,signal);}}
    public static final class Home extends LiteHomeActivity {Data data;protected boolean allowAutomaticChecks(){return false;}protected LiteAntennaData createAntennaData(){if(data==null)data=new Data(this);return data;}}
    public Activity newActivity(ClassLoader loader,String name,Intent intent)throws InstantiationException,IllegalAccessException,ClassNotFoundException{return name.equals(LiteHomeActivity.class.getName())?new Home():super.newActivity(loader,name,intent);}
    private Context context;private Home activity;private String previous,profile;private final Map<String,String> checks=new LinkedHashMap<>();private final List<File> files=new ArrayList<>();
    interface Step {void run()throws Exception;}interface Ready {boolean ready()throws Exception;}void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}void ui(Runnable task){Throwable[] error={null};runOnMainSync(()->{try{task.run();}catch(Throwable e){error[0]=e;}});waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}void key(int code){sendKeyDownUpSync(code);waitForIdleSync();}
    Object field(Object target,String name)throws Exception{for(Class<?> c=target.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(name);f.setAccessible(true);return f.get(target);}catch(NoSuchFieldException absent){}throw new NoSuchFieldException(name);}void await(Ready ready)throws Exception{long end=SystemClock.elapsedRealtime()+15000;while(SystemClock.elapsedRealtime()<end){waitForIdleSync();if(ready.ready())return;Thread.sleep(60);}throw new AssertionError("Fixture did not settle");}void runCase(String name,Step step){try{step.run();checks.put(name,"PASS");}catch(Throwable e){checks.put(name,"FAIL "+e);}}
    LiteAntennaGuide guide()throws Exception{return (LiteAntennaGuide)field(activity,"guide");}TvTimelineView timeline()throws Exception{return (TvTimelineView)field(guide(),"timeline");}int row()throws Exception{return (Integer)field(timeline(),"row");}void png(File file,int color)throws Exception{file.getParentFile().mkdirs();Bitmap b=Bitmap.createBitmap(64,64,Bitmap.Config.ARGB_8888);b.eraseColor(color);try(OutputStream out=new FileOutputStream(file)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();files.add(file);}
    static String stamp(long sec){SimpleDateFormat f=new SimpleDateFormat("yyyyMMddHHmmss Z",Locale.ROOT);f.setTimeZone(TimeZone.getTimeZone("UTC"));return f.format(new Date(sec*1000));}
    void fixture()throws Exception{png(new File(context.getCacheDir(),"tv-regression-native.png"),Color.RED);StringBuilder xml=new StringBuilder("<tv>");long now=System.currentTimeMillis()/1000;for(int i=1;i<=36;i++){String url="https://raw.githubusercontent.com/davidmuma/picons_dobleM/master/vela-test-"+i+".png";png(new File(context.getCacheDir(),"antenna-epg/logos/"+LiveTvData.hash(url)+".png"),i==2?Color.BLUE:Color.RED);xml.append("<channel id='demo").append(i).append("'><display-name>Canal Demo ").append(String.format(Locale.ROOT,"%02d",i)).append("</display-name><icon src='").append(url).append("'/></channel>");}for(int i=1;i<=36;i++)xml.append("<programme channel='demo").append(i).append("' start='").append(stamp(now-1200)).append("' stop='").append(stamp(now+7200)).append("'><title>Programa Demo ").append(i).append("</title></programme>");new LiteXmlTvGuide(context).importGuide(new ByteArrayInputStream(xml.append("</tv>").toString().getBytes("UTF-8")),new Data(context).channels(new CancellationSignal()),now,new CancellationSignal());}
    void paging()throws Exception{int rows=VelaReading.rows(context);await(()->timeline()!=null&&timeline().hasFocus()&&!(Boolean)field(guide(),"loading"));List<LiveTvData.Channel> all=(List<LiveTvData.Channel>)field(guide(),"filtered");for(int i=1;i<rows;i++)key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_DPAD_DOWN);await(()->(Integer)field(guide(),"page")==1);check(row()==0&&((LiveTvData.Channel)field(guide(),"selected")).id.equals(all.get(rows).id),"Next antenna page did not select its first channel");key(KeyEvent.KEYCODE_DPAD_UP);await(()->(Integer)field(guide(),"page")==0);check(row()==rows-1,"Previous antenna page did not select its final channel");Thread.sleep(300);check(row()==rows-1,"Async antenna programme completion changed selection");}
    void refreshReturn()throws Exception{View navigation=((View[])field(activity,"navigation"))[1];String selected=((LiveTvData.Channel)field(guide(),"selected")).id;int reads=activity.data.reads;ui(navigation::requestFocus);ui(()->{try{guide().reload(true);}catch(Exception e){throw new RuntimeException(e);}});await(()->activity.data.reads>reads&&!(Boolean)field(guide(),"loading"));check(navigation.hasFocus(),"Antenna reload stole sidebar focus");key(KeyEvent.KEYCODE_DPAD_RIGHT);await(()->timeline().hasFocus());check(((LiveTvData.Channel)field(guide(),"selected")).id.equals(selected),"Returning after EPG refresh discarded the selected channel");}
    void logos()throws Exception{LiveTvData.Channel ch=new Data(context).channels(new CancellationSignal()).get(0);LiteTvUi.Logos loader=new LiteTvUi.Logos(context);try{Bitmap a=loader.read(ch);check(a!=null&&a.getPixel(20,20)==Color.RED,"Native logo fixture unavailable");VelaGuideFix.set(context,ch.name,"demo2",0);Bitmap b=loader.read(ch);check(b!=null&&b.getPixel(20,20)==Color.BLUE,"Corrected EPG retained the native logo or its old cache entry");check(new LiteXmlTvGuide(context).read(Collections.singletonList(ch),System.currentTimeMillis()/1000,System.currentTimeMillis()/1000+3600,new CancellationSignal()).get(ch.id).get(0).title.equals("Programa Demo 2"),"Antenna logo and schedule use different corrected identities");VelaGuideFix.reset(context,ch.name);check(loader.read(ch).getPixel(20,20)==Color.RED,"Automatic matching did not restore the native logo");check(loader.cache.size()<=512*1024,"Lite decoded-logo cache grew");}finally{VelaGuideFix.reset(context,ch.name);loader.close();}}
    public void onCreate(Bundle b){super.onCreate(b);start();}public void onStart(){Bundle result=new Bundle();context=getTargetContext();try{try(ParcelFileDescriptor f=getUiAutomation().executeShellCommand("getprop ro.kernel.qemu");InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(f)){check(in.read()=='1',"Owned emulator required");}previous=VelaWorkspace.active(context);profile=VelaWorkspace.create(context,"TV Fix "+SystemClock.elapsedRealtime());VelaWorkspace.select(context,profile);L10n.choose(context,"es");Ui.init(context);VelaWorkspace.prefs(context,"lite_updates").edit().putBoolean("automatic",false).commit();VelaWorkspace.prefs(context,"lite_tv").edit().putBoolean("online_guide",true).putBoolean("channel_view",false).commit();fixture();activity=(Home)startActivitySync(new Intent(context,LiteHomeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));View[] nav=(View[])field(activity,"navigation");ui(nav[1]::performClick);runCase("antenna_paging",this::paging);runCase("refresh_return",this::refreshReturn);runCase("corrected_logo",this::logos);for(Map.Entry<String,String> entry:checks.entrySet())result.putString(entry.getKey(),entry.getValue());}catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{try{if(activity!=null)ui(activity::finish);if(profile!=null){VelaWorkspace.select(context,previous);VelaWorkspace.delete(context,profile);}}catch(Exception ignored){}for(File file:files)file.delete();}boolean ok=!result.containsKey("error")&&checks.size()==3;for(String value:checks.values())ok&=value.equals("PASS");result.putString("result",ok?"PASS native Lite forward/back paging and async selection, corrected EPG logo priority/cache identity, automatic native-logo restoration and existing 512KiB cache budget. Read-only tuner fixture; no playback, network request or personal credential.":"FAIL Lite TV regressions");finish(ok?-1:1,result);}
}
